! ============================================================
! VML 网络扩展库 — Fortran
!
! 使用示例:
!   call asm("SYSCALL 330")   ! 创建套接字
!   call asm("SYSCALL 331")   ! 绑定端口
!   call asm("SYSCALL 332")   ! 监听连接
!   call asm("SYSCALL 333")   ! 接受连接
!   call asm("SYSCALL 334")   ! 连接到服务器
!   call asm("SYSCALL 335")   ! 发送数据
!   call asm("SYSCALL 336")   ! 接收数据
!   call asm("SYSCALL 337")   ! 关闭套接字
!   call asm("SYSCALL 338")   ! DNS 解析
!
! 注意: 仅在 OS 模式 (--mode os) 下可用
! ============================================================

! ============================================================
! SYSCALL 330 — SocketCreate
! 创建套接字
! 参数:
!   R0 = 地址族: 2=AF_INET (IPv4)
!   R1 = 类型: 1=SOCK_STREAM (TCP), 其他=SOCK_DGRAM (UDP)
! 返回: R0 = 套接字句柄 fd (>0 成功), <0 失败
!
! Fortran 使用示例:
!   ! 创建 TCP 套接字
!   ! R0 = 2 (AF_INET), R1 = 1 (SOCK_STREAM)
!   call asm("SYSCALL 330")
!   ! 返回: R0 = fd
! ============================================================

! ============================================================
! SYSCALL 331 — SocketBind
! 绑定端口到套接字
! 参数:
!   R0 = fd
!   R1 = 端口号
! 返回: R0 = 0 成功, <0 失败
!
! Fortran 使用示例:
!   ! 绑定端口 8080
!   ! R0 = fd, R1 = 8080
!   call asm("SYSCALL 331")
! ============================================================

! ============================================================
! SYSCALL 332 — SocketListen
! 监听连接请求
! 参数:
!   R0 = fd
!   R1 = backlog (队列长度)
! 返回: R0 = 0 成功, <0 失败
!
! Fortran 使用示例:
!   ! 开始监听，backlog=5
!   ! R0 = fd, R1 = 5
!   call asm("SYSCALL 332")
! ============================================================

! ============================================================
! SYSCALL 333 — SocketAccept
! 接受客户端连接 (阻塞)
! 参数: R0 = fd (监听套接字)
! 返回: R0 = 客户端 fd (>0 成功), <0 失败
!
! Fortran 使用示例:
!   ! 接受连接
!   ! R0 = fd (listening socket)
!   call asm("SYSCALL 333")
!   ! 返回: R0 = client_fd
! ============================================================

! ============================================================
! SYSCALL 334 — SocketConnect
! 连接到远程服务器
! 参数:
!   R0 = fd
!   R1 = IP 地址字符串地址 (如 "127.0.0.1\0")
!   R2 = 端口号
! 返回: R0 = 0 成功, <0 失败
!
! Fortran 使用示例:
!   ! 连接到 127.0.0.1:8080
!   ! R0 = fd, R1 = IP 地址, R2 = 8080
!   call asm("SYSCALL 334")
! ============================================================

! ============================================================
! SYSCALL 335 — SocketSend
! 发送数据
! 参数:
!   R0 = fd
!   R1 = 数据地址
!   R2 = 字节数
! 返回: R0 = 实际发送字节数, <0 失败
!
! Fortran 使用示例:
!   ! 发送 1024 字节
!   ! R0 = fd, R1 = 数据地址, R2 = 1024
!   call asm("SYSCALL 335")
! ============================================================

! ============================================================
! SYSCALL 336 — SocketRecv
! 接收数据
! 参数:
!   R0 = fd
!   R1 = 缓冲区地址
!   R2 = 缓冲区大小
! 返回: R0 = 实际接收字节数 (0=连接关闭), <0 失败
!
! Fortran 使用示例:
!   ! 接收最多 4096 字节
!   ! R0 = fd, R1 = 缓冲区地址, R2 = 4096
!   call asm("SYSCALL 336")
! ============================================================

! ============================================================
! SYSCALL 337 — SocketClose
! 关闭套接字
! 参数: R0 = fd
! 返回: R0 = 0 成功, <0 失败
!
! Fortran 使用示例:
!   ! R0 = fd
!   call asm("SYSCALL 337")
! ============================================================

! ============================================================
! SYSCALL 338 — DnsResolve
! DNS 域名解析
! 参数: R0 = 主机名地址 (\0 结尾)
! 返回: R0 = IP 地址 (32-bit 整数), 0 = 失败
!
! Fortran 使用示例:
!   ! 解析 "example.com"
!   ! R0 = 主机名字符串地址
!   call asm("SYSCALL 338")
!   ! 返回: R0 = IP 地址 (如 0x7F000001 = 127.0.0.1)
! ============================================================

! ============================================================
! VML 汇编共享库 CALL 目标 (网络):
!   CALL net_connect   — TCP 连接
!   CALL net_send      — 发送数据
!   CALL net_recv      — 接收数据
!   CALL net_close     — 关闭连接
!   CALL net_listen    — TCP 监听
! ============================================================
